#[test]
fn test_room_mesh_has_no_unpaired_interior_faces() {
    use std::collections::HashMap;

    let simulation = RoomSimulation::new(
        RoomGeometry::Rectangular(RectangularRoom::new(1.6, 1.5, 1.4)),
        vec![Source::omnidirectional(Point3D::new(0.4, 0.35, 0.35), 1.0)],
        vec![Point3D::new(1.2, 1.1, 1.0)],
    );
    for grading_factor in [1.0, 2.0] {
        let config = FemMeshConfig {
            grading_factor,
            fine_radius: 0.15,
            ..FemMeshConfig::default()
        };
        let mesh = create_room_mesh(&simulation, 4, &SymmetryConfig::none(), &config);
        let mut incidence = HashMap::<[usize; 3], usize>::new();
        for element in &mesh.elements {
            let vertices = element.vertices();
            for excluded in 0..4 {
                let mut face = [0; 3];
                let mut next = 0;
                for (index, &vertex) in vertices.iter().enumerate() {
                    if index != excluded {
                        face[next] = vertex;
                        next += 1;
                    }
                }
                face.sort_unstable();
                *incidence.entry(face).or_default() += 1;
            }
        }
        for (face, count) in incidence {
            assert!((1..=2).contains(&count), "nonmanifold face {face:?}");
            if count == 1 {
                let on_wall = [1.6, 1.5, 1.4].iter().enumerate().any(|(axis, &length)| {
                    [0.0, length].iter().any(|&coordinate| {
                        face.iter().all(|&node| {
                            let point = &mesh.nodes[node];
                            ([point.x, point.y, point.z][axis] - coordinate).abs() < 1e-12
                        })
                    })
                });
                assert!(
                    on_wall,
                    "unpaired interior face {face:?}; grading={grading_factor}"
                );
            }
        }
    }
}
