/// Symmetry-exploiting FEM solve.
///
/// Meshes only the reduced domain (half or quarter room). For each source,
/// decomposes into 2^N modes (N = number of symmetry planes), solving each
/// with the appropriate BC on the cut planes (Neumann for even, Dirichlet for
/// odd). Reconstructs the full solution at each listening position.
#[cfg(test)]
fn run_fem_symmetric(
    simulation: &RoomSimulation,
    symmetry: &SymmetryConfig,
    mesh_config: &FemMeshConfig,
) -> Result<SimulationOutput> {
    Ok(run_fem_symmetric_report(simulation, symmetry, mesh_config)?.0)
}

/// Assemble RHS vector with parallel element processing.
///
/// `image_walls_aabb` defines the set of axis-aligned planes across which
/// near-wall sources should be mirrored to compensate for Gaussian truncation.
/// In the full solve this is the mesh AABB (= the room itself). In the
/// symmetric solve it must be the *full room* AABB, **not** the half-domain
/// mesh AABB, because cut-plane symmetries are handled by the matrix-level
/// Dirichlet/Neumann conditions per parity mode — and a parity-unaware
/// positive image across a cut plane would corrupt the odd-mode RHS.
#[cfg(test)]
fn assemble_rhs_parallel(
    mesh: &Mesh,
    sources: &[Source],
    image_walls_aabb: ([f64; 3], [f64; 3]),
    frequency: f64,
    source_width: f64,
) -> Vec<Complex64> {
    let n_dofs = mesh.num_nodes();
    let n_elems = mesh.num_elements();
    let cutoff = SOURCE_TRUNCATION_SIGMAS * source_width;
    let cutoff_sq = cutoff * cutoff;

    // Pre-expand each source into its image-corrected position list. Each
    // image radiates the same monopole strength as the original (Neumann
    // mirror), so we just remember the positions per source.
    let source_positions: Vec<Vec<Point3D>> = sources
        .iter()
        .map(|s| image_positions(s.position, image_walls_aabb, cutoff))
        .collect();

    // Source-truncated assembly: most elements are far from every source and
    // contribute nothing. Use a sparse fold/reduce accumulator instead of
    // collecting an n_elems-sized Vec<Vec<...>> — that header array alone is
    // ~32 bytes per element (32 MB for 1 M-element meshes) before any
    // contributions go in. Each rayon task instead appends only the
    // non-trivial contributions into a per-task Vec, and the reduce step
    // concatenates the (typically small) per-task buffers.
    let combined: Vec<(usize, Complex64)> = (0..n_elems)
        .into_par_iter()
        .fold(Vec::new, |mut acc, elem_idx| {
            let elem = &mesh.elements[elem_idx];
            let elem_type = elem.element_type;
            let vertices = elem.vertices();
            let n_nodes = vertices.len();

            let quad = for_mass(elem_type, 1);

            let coords: Vec<[f64; 3]> = vertices
                .iter()
                .map(|&v| [mesh.nodes[v].x, mesh.nodes[v].y, mesh.nodes[v].z])
                .collect();

            // AABB-distance check uses the union of all effective positions.
            let any_near = source_positions
                .iter()
                .flatten()
                .any(|sp| point_aabb_distance_sq(*sp, &coords) <= cutoff_sq);
            if !any_near {
                return acc;
            }

            for qp in quad.iter() {
                let shape = evaluate_shape(
                    elem_type,
                    PolynomialDegree::P1,
                    qp.xi(),
                    qp.eta(),
                    qp.zeta(),
                );
                let jac = Jacobian::from_3d(&shape.gradients, shape.grad_dim, &coords);

                let x: f64 = shape
                    .values
                    .iter()
                    .zip(&coords)
                    .map(|(n, c)| n * c[0])
                    .sum();
                let y: f64 = shape
                    .values
                    .iter()
                    .zip(&coords)
                    .map(|(n, c)| n * c[1])
                    .sum();
                let z: f64 = shape
                    .values
                    .iter()
                    .zip(&coords)
                    .map(|(n, c)| n * c[2])
                    .sum();

                let f_val = compute_source_term(
                    x,
                    y,
                    z,
                    sources,
                    &source_positions,
                    frequency,
                    source_width,
                );
                let det_j = jac.det.abs();

                for (i, &vertex) in vertices.iter().enumerate().take(n_nodes) {
                    let contrib = f_val * Complex64::new(shape.values[i] * det_j * qp.weight, 0.0);
                    if contrib.norm() > 1e-15 {
                        acc.push((vertex, contrib));
                    }
                }
            }

            acc
        })
        .reduce(Vec::new, |mut a, b| {
            if a.is_empty() {
                b
            } else if b.is_empty() {
                a
            } else {
                a.extend(b);
                a
            }
        });

    let mut rhs = vec![Complex64::new(0.0, 0.0); n_dofs];
    for (node_idx, val) in combined {
        rhs[node_idx] += val;
    }

    rhs
}

