#[test]
fn test_amplitude_calibration_targets_85_db_at_1m_1khz() {
    let f = 1_000.0;
    let omega = 2.0 * std::f64::consts::PI * f;
    let q = SOURCE_VOLUME_VELOCITY_REFERENCE;
    let p_pa = omega * AIR_DENSITY * q / (4.0 * std::f64::consts::PI);
    let spl_db = 20.0 * (p_pa / 20.0e-6).log10();
    assert!(
        (83.0..87.0).contains(&spl_db),
        "amplitude=1 should radiate ≈85 dB SPL at 1 m, 1 kHz; got {spl_db:.2} dB"
    );
}
#[test]
fn test_bicgstab_fallback_preserves_exact_failed_iterate() {
    let operator: CsrMatrix<Complex64> = CsrMatrix::identity(2);
    let preconditioner = FemPreconditioner::Ilut(IlutPreconditioner::from_csr(&operator));
    let rhs = [Complex64::new(1.0, 0.5), Complex64::new(-2.0, 0.25)];
    let solution =
        solve_frequency_system_bicgstab(&operator, &preconditioner, &rhs, Some(&rhs), 1.0e-12);
    assert!(solution.converged);
    assert_eq!(solution.iterations, 0);
    assert!(solution.residual <= 1.0e-12);
}
#[test]
fn test_symmetry_cancellation_preserves_first_fatal_error() {
    let cancellation = SymmetryCancellation::default();
    assert!(!cancellation.is_cancelled());
    cancellation.cancel("mode 1 failed at 410.6 Hz".to_string());
    cancellation.cancel("mode 0 was cancelled later".to_string());
    assert!(cancellation.is_cancelled());
    assert_eq!(
        cancellation.first_error().as_deref(),
        Some("mode 1 failed at 410.6 Hz")
    );
}
