#[test]
fn test_fem_rhs_applies_source_amplitude_crossover_and_directivity() {
    let position = Point3D::new(0.5, 0.5, 0.5);
    let room = RectangularRoom::new(1.0, 1.0, 1.0);
    let sim = RoomSimulation::with_frequencies(
        RoomGeometry::Rectangular(room),
        vec![Source::omnidirectional(position, 1.0)],
        vec![Point3D::new(0.75, 0.7, 0.55)],
        20.0,
        200.0,
        3,
    );
    let mesh_config = FemMeshConfig {
        fine_radius: 0.35,
        ..FemMeshConfig::default()
    };
    let mesh = create_room_mesh(&sim, 4, &SymmetryConfig::none(), &mesh_config);
    let image_walls_aabb = mesh_aabb(&mesh);
    let frequency = 100.0;
    let unit_source = Source::omnidirectional(position, 1.0);
    let double_source = Source::omnidirectional(position, 2.0);
    let directional_source =
        Source::classical(position, 35.0, 25.0, 1.0).with_orientation(Point3D::new(1.0, -1.0, 0.2));
    let filtered_source =
        Source::omnidirectional(position, 1.0).with_crossover(CrossoverFilter::Highpass {
            cutoff_freq: 200.0,
            order: 4,
        });
    let rhs_unit = assemble_rhs_parallel(
        &mesh,
        &[unit_source],
        image_walls_aabb,
        frequency,
        DEFAULT_SOURCE_WIDTH,
    );
    let rhs_double = assemble_rhs_parallel(
        &mesh,
        &[double_source],
        image_walls_aabb,
        frequency,
        DEFAULT_SOURCE_WIDTH,
    );
    let rhs_directional = assemble_rhs_parallel(
        &mesh,
        &[directional_source],
        image_walls_aabb,
        frequency,
        DEFAULT_SOURCE_WIDTH,
    );
    let crossover_scale = room_complex_isotropic_amplitude(&filtered_source, frequency);
    let rhs_filtered = assemble_rhs_parallel(
        &mesh,
        &[filtered_source],
        image_walls_aabb,
        frequency,
        DEFAULT_SOURCE_WIDTH,
    );
    assert!(
        rhs_norm(&rhs_unit) > 0.0,
        "test mesh should receive source energy"
    );
    assert_scaled_rhs_eq(&rhs_unit, &rhs_double, 2.0);
    let directional_difference = rhs_unit
        .iter()
        .zip(&rhs_directional)
        .map(|(omni, directional)| (*omni - *directional).norm_sqr())
        .sum::<f64>()
        .sqrt();
    assert!(
        directional_difference > 0.05 * rhs_norm(&rhs_unit),
        "directional source must alter the spatial FEM forcing"
    );
    assert_scaled_rhs_eq_complex(&rhs_unit, &rhs_filtered, crossover_scale);
}

#[test]
fn test_room_crossover_phase_preserves_two_source_interference_null() {
    let basis = SourceRhsBasis {
        entries: vec![(0, 1.0, Point3D::new(0.0, 1.0, 0.0))],
        scale_base: 1.0,
    };
    let pattern = |phase: Complex64| {
        Directivity::ComplexGrid(
            ComplexDirectivityGrid::try_new(
                vec![0.0, 90.0, 180.0, 270.0],
                vec![0.0, 90.0, 180.0],
                vec![500.0],
                vec![HostMatrix::from_elem(3, 4, phase)],
            )
            .expect("uniform complex directivity grid is valid"),
        )
    };

    // At its cutoff, a second-order LP has magnitude 1/sqrt(2).  The
    // sqrt(2) source therefore contributes +i in the room convention after
    // conjugation.  The second source contributes -i through its measured
    // complex directivity phase, so the two physical source terms cancel.
    let filtered = Source::new(
        Point3D::new(0.0, 0.0, 0.0),
        pattern(Complex64::new(1.0, 0.0)),
        2.0_f64.sqrt(),
    )
    .with_crossover(CrossoverFilter::Lowpass {
        cutoff_freq: 500.0,
        order: 2,
    });
    let phase_shifted = Source::new(
        Point3D::new(0.0, 0.0, 0.0),
        pattern(Complex64::new(0.0, -1.0)),
        1.0,
    );
    let filtered_rhs = assemble_rhs_from_basis(&basis, &filtered, 500.0, 1);
    let phase_shifted_rhs = assemble_rhs_from_basis(&basis, &phase_shifted, 500.0, 1);
    let residual = filtered_rhs[0] + phase_shifted_rhs[0];
    assert!(
        residual.norm() < 1.0e-10,
        "room-side crossover phase must preserve the two-source null: {residual}"
    );
}
