#[test]
fn test_listener_interpolation_cache_matches_direct_evaluation() {
    let room = RectangularRoom::new(1.6, 1.4, 1.2);
    let lp = Point3D::new(0.9, 0.8, 0.7);
    let sim = RoomSimulation::with_frequencies(
        RoomGeometry::Rectangular(room),
        vec![Source::omnidirectional(Point3D::new(0.4, 0.5, 0.6), 1.0)],
        vec![lp],
        40.0,
        200.0,
        3,
    );
    let mesh_config = FemMeshConfig {
        fine_radius: 0.35,
        ..FemMeshConfig::default()
    };
    let mesh = create_room_mesh(&sim, 5, &SymmetryConfig::none(), &mesh_config);
    let containing = vec![find_containing_element_parallel(&mesh, lp)];
    let (cached, fallbacks) = build_listener_interpolations(&mesh, &[lp], &containing);
    assert_eq!(
        fallbacks, 0,
        "in-mesh listener must not use the nearest-node fallback"
    );
    let solution: Vec<Complex64> = (0..mesh.num_nodes())
        .map(|i| Complex64::new(i as f64 * 0.25, -(i as f64) * 0.125))
        .collect();
    let direct = evaluate_solution_at_point_interpolated(&mesh, &solution, lp, containing[0]);
    let from_cache = evaluate_listener_interpolation(&solution, &cached[0]);
    assert!(
        (direct - from_cache).norm() < 1.0e-12,
        "cached listener interpolation drifted from direct evaluation: direct={direct:?}, cached={from_cache:?}"
    );
}
#[test]
fn test_fem_rhs_basis_matches_direct_assembly() {
    let position = Point3D::new(0.8, 0.7, 0.65);
    let frequency = 125.0;
    let source = Source::omnidirectional(position, 1.25).with_crossover(CrossoverFilter::Lowpass {
        cutoff_freq: 200.0,
        order: 4,
    });
    let room = RectangularRoom::new(1.6, 1.4, 1.2);
    let sim = RoomSimulation::with_frequencies(
        RoomGeometry::Rectangular(room),
        vec![source.clone()],
        vec![Point3D::new(1.1, 0.9, 0.65)],
        40.0,
        200.0,
        3,
    );
    let mesh_config = FemMeshConfig {
        fine_radius: 0.35,
        ..FemMeshConfig::default()
    };
    let mesh = create_room_mesh(&sim, 5, &SymmetryConfig::none(), &mesh_config);
    let image_walls_aabb = mesh_aabb(&mesh);
    let direct = assemble_rhs_parallel(
        &mesh,
        std::slice::from_ref(&source),
        image_walls_aabb,
        frequency,
        DEFAULT_SOURCE_WIDTH,
    );
    let basis = build_source_rhs_basis(&mesh, &source, image_walls_aabb, DEFAULT_SOURCE_WIDTH);
    let from_basis = assemble_rhs_from_basis(&basis, &source, frequency, mesh.num_nodes());
    let max_abs = direct
        .iter()
        .zip(from_basis.iter())
        .map(|(a, b)| (a - b).norm())
        .fold(0.0, f64::max);
    let scale = rhs_norm(&direct).max(1e-30);
    assert!(
        max_abs / scale < 1.0e-12,
        "precomputed RHS basis drifted from direct assembly: max_abs={max_abs:.3e}, scale={scale:.3e}"
    );
}

#[test]
fn test_gpu_rhs_basis_selection_matches_cpu_source_model() {
    let position = Point3D::new(0.55, 0.6, 0.45);
    let source = Source::omnidirectional(position, 1.0);
    let room = RectangularRoom::new(1.2, 1.1, 0.9);
    let sim = RoomSimulation::with_frequencies(
        RoomGeometry::Rectangular(room),
        vec![source.clone()],
        vec![Point3D::new(0.8, 0.7, 0.5)],
        100.0,
        100.0,
        1,
    );
    let mesh_config = FemMeshConfig {
        fine_radius: 0.3,
        ..FemMeshConfig::default()
    };
    let mesh = create_room_mesh(&sim, 6, &SymmetryConfig::none(), &mesh_config);
    let image_walls_aabb = mesh_aabb(&mesh);

    for source_model in [
        FemSourceModel::PointLoad,
        FemSourceModel::Gaussian { sigma: 0.07 },
    ] {
        let selected =
            build_source_rhs_basis_for_model(&mesh, &source, image_walls_aabb, source_model)
                .expect("in-mesh test source must build an RHS basis");
        let reference = match source_model {
            FemSourceModel::PointLoad => build_point_source_rhs_basis(&mesh, &source)
                .expect("in-mesh test source must build a point RHS basis"),
            FemSourceModel::Gaussian { sigma } => {
                build_source_rhs_basis(&mesh, &source, image_walls_aabb, sigma)
            }
        };
        let selected_rhs = assemble_rhs_from_basis(&selected, &source, 100.0, mesh.num_nodes());
        let reference_rhs = assemble_rhs_from_basis(&reference, &source, 100.0, mesh.num_nodes());
        let max_abs = selected_rhs
            .iter()
            .zip(&reference_rhs)
            .map(|(selected, reference)| (*selected - *reference).norm())
            .fold(0.0, f64::max);
        assert!(
            max_abs < 1.0e-12,
            "configured source model must produce identical host RHS basis across runners: model={source_model:?}, max_abs={max_abs:.3e}"
        );
    }
}
#[test]
fn test_fem_rhs_integrates_to_monopole_strength() {
    let position = Point3D::new(0.6, 0.6, 0.6);
    let amplitude = 1.5;
    let frequency = 250.0;
    let source_width = 0.12;
    let source = Source::omnidirectional(position, amplitude);
    let room = RectangularRoom::new(1.2, 1.2, 1.2);
    let sim = RoomSimulation::with_frequencies(
        RoomGeometry::Rectangular(room),
        vec![source.clone()],
        vec![Point3D::new(0.9, 0.7, 0.65)],
        frequency,
        frequency,
        1,
    );
    let mesh_config = FemMeshConfig {
        fine_radius: 0.55,
        ..FemMeshConfig::default()
    };
    let mesh = create_room_mesh(&sim, 12, &SymmetryConfig::none(), &mesh_config);
    let rhs = assemble_rhs_parallel(&mesh, &[source], mesh_aabb(&mesh), frequency, source_width);
    let integrated = rhs.iter().copied().sum::<Complex64>();
    let expected = Complex64::new(
        0.0,
        -2.0 * std::f64::consts::PI
            * frequency
            * AIR_DENSITY
            * SOURCE_VOLUME_VELOCITY_REFERENCE
            * amplitude,
    );
    let rel_error = (integrated - expected).norm() / expected.norm();
    assert!(
        integrated.re.abs() < expected.norm() * 1.0e-12,
        "monopole RHS should be purely imaginary: got {integrated:?}"
    );
    assert!(
        rel_error < 0.08,
        "integrated RHS should match analytic monopole strength: expected={expected:?}, got={integrated:?}, rel_error={rel_error:.3e}"
    );
}

/// The discrete-delta (point-load) source must integrate to the prescribed
/// monopole strength EXACTLY on any mesh: its shape-function weights are a
/// partition of unity, so the integrated load is mesh- and frequency-
/// independent. The fixed-width Gaussian only converges to this in the
/// σ → 0 limit.
#[test]
fn test_point_source_basis_integrates_to_monopole_strength_on_any_mesh() {
    let position = Point3D::new(0.6, 0.6, 0.6);
    let amplitude = 1.5;
    let frequency = 250.0;
    let source = Source::omnidirectional(position, amplitude);
    let room = RectangularRoom::new(1.2, 1.2, 1.2);
    let sim = RoomSimulation::with_frequencies(
        RoomGeometry::Rectangular(room),
        vec![source.clone()],
        vec![Point3D::new(0.9, 0.7, 0.65)],
        frequency,
        frequency,
        1,
    );
    let expected = Complex64::new(
        0.0,
        -2.0 * std::f64::consts::PI
            * frequency
            * AIR_DENSITY
            * SOURCE_VOLUME_VELOCITY_REFERENCE
            * amplitude,
    );
    for elements_per_wavelength in [6_usize, 12] {
        let mesh_config = FemMeshConfig {
            fine_radius: 0.55,
            source_model: FemSourceModel::PointLoad,
            ..FemMeshConfig::default()
        };
        let mesh = create_room_mesh(
            &sim,
            elements_per_wavelength,
            &SymmetryConfig::none(),
            &mesh_config,
        );
        let basis = build_point_source_rhs_basis(&mesh, &source)
            .expect("in-mesh test source must build a point RHS basis");
        let rhs = assemble_rhs_from_basis(&basis, &source, frequency, mesh.num_nodes());
        let integrated = rhs.iter().copied().sum::<Complex64>();
        let rel_error = (integrated - expected).norm() / expected.norm();
        assert!(
            rel_error < 1.0e-12,
            "point-load RHS strength must be mesh-independent: epw={elements_per_wavelength}, \
             expected={expected:?}, got={integrated:?}, rel_error={rel_error:.3e}"
        );
    }
}

