/// Free-field calibration across the simulated band: in a room with matched
/// (anechoic) boundaries, the point-load monopole must track the analytical
/// free-field magnitude ωρQ/(4πr) from 200 Hz to 800 Hz. The historical
/// fixed 0.1 m Gaussian fails this test at 800 Hz, where its
/// exp(-(kσ)²/2) roll-off leaves only ~34% of the monopole amplitude.
#[test]
fn test_free_field_point_source_tracks_greens_function_across_band() {
    let source_pos = Point3D::new(0.4, 0.35, 0.35);
    let listeners = vec![
        Point3D::new(1.2, 1.1, 1.0),
        Point3D::new(1.0, 0.95, 0.9),
        Point3D::new(1.25, 0.6, 0.85),
        Point3D::new(0.75, 1.1, 0.9),
    ];
    let mut sim = RoomSimulation::new(
        RoomGeometry::Rectangular(RectangularRoom::new(1.6, 1.5, 1.4)),
        vec![Source::omnidirectional(source_pos, 1.0)],
        listeners.clone(),
    );
    // Matched boundaries: normalized admittance β = ρc/Z = 1 absorbs
    // (nearly) all incident energy, approximating free field.
    sim.boundaries = BoundaryConfig {
        floor: SurfaceConfig::Admittance {
            real: 1.0,
            imag: 0.0,
        },
        ceiling: SurfaceConfig::Admittance {
            real: 1.0,
            imag: 0.0,
        },
        walls: SurfaceConfig::Admittance {
            real: 1.0,
            imag: 0.0,
        },
        front_wall: None,
        back_wall: None,
        left_wall: None,
        right_wall: None,
    };
    sim.frequencies = vec![200.0, 400.0, 800.0];
    let output = run_fem_with_mesh(
        &sim,
        &FemMeshConfig {
            fine_radius: 0.4,
            // Boundary loss supplies the physical decay; no numerical floor.
            modal_damping_ratio: 0.0,
            source_model: FemSourceModel::PointLoad,
            ..FemMeshConfig::default()
        },
    )
    .expect("free-field calibration solve should converge");

    output
        .require_solved("spatial free-field correlation")
        .expect("FEM spatial field must retain solved provenance");
    let reference = SpatialFieldReference::monopole(
        source_pos,
        listeners,
        sim.frequencies.clone(),
        sim.speed_of_sound,
        SOURCE_VOLUME_VELOCITY_REFERENCE,
    )
    .expect("independent free-field reference should be valid");
    assert_eq!(
        reference.provenance,
        SpatialFieldProvenance::AnalyticMonopoleGreenFunction
    );
    reference
        .validate_layout()
        .expect("reference field layout should be valid");

    for (listener_idx, reference_pressures) in reference.pressures.iter().enumerate() {
        for (freq_idx, &frequency) in sim.frequencies.iter().enumerate() {
            let free_field = reference_pressures[freq_idx].norm();
            let numerical = output.pressures[0][listener_idx][freq_idx].norm();
            let ratio = numerical / free_field;
            assert!(
                (0.6..=1.7).contains(&ratio),
                "point-load monopole must track the free-field Green's function across the spatial stencil: listener={listener_idx}, f={frequency:.0} Hz, |p|={numerical:.4e}, reference={free_field:.4e}, ratio={ratio:.3}"
            );
        }
    }
}
#[test]
fn test_rigid_rectangular_room_peaks_near_first_axial_mode() {
    let width = 1.0;
    let depth = 0.8;
    let height = 0.7;
    let mut sim = RoomSimulation::new(
        RoomGeometry::Rectangular(RectangularRoom::new(width, depth, height)),
        vec![Source::omnidirectional(Point3D::new(0.18, 0.31, 0.29), 1.0)],
        vec![Point3D::new(0.83, 0.57, 0.41)],
    );
    let expected_first_axial =
        rectangular_mode_frequency(1, 0, 0, width, depth, height, sim.speed_of_sound);
    sim.frequencies = vec![
        expected_first_axial - 28.0,
        expected_first_axial - 14.0,
        expected_first_axial - 5.0,
        expected_first_axial,
        expected_first_axial + 5.0,
        expected_first_axial + 14.0,
        expected_first_axial + 28.0,
    ];
    let output = run_fem_with_mesh(
        &sim,
        &FemMeshConfig {
            fine_radius: 0.35,
            modal_damping_ratio: 0.003,
            ..FemMeshConfig::default()
        },
    )
    .expect("rigid rectangular modal sweep should converge");
    let magnitudes: Vec<f64> = output.pressures[0][0].iter().map(|p| p.norm()).collect();
    let (peak_idx, peak_mag) = magnitudes
        .iter()
        .copied()
        .enumerate()
        .max_by(|(_, a), (_, b)| a.total_cmp(b))
        .unwrap();
    let peak_freq = output.frequencies[peak_idx];
    assert!(
        (peak_freq - expected_first_axial).abs() <= 5.0,
        "rigid room peak should land near first axial mode {expected_first_axial:.2} Hz, got {peak_freq:.2} Hz"
    );
    assert!(
        peak_mag > magnitudes[0] * 1.5 && peak_mag > magnitudes[6] * 1.5,
        "modal peak should stand above sweep edges: peak={peak_mag:.3e}, low={:.3e}, high={:.3e}",
        magnitudes[0],
        magnitudes[6]
    );
}
#[test]
fn test_full_fem_runner_recovers_rigid_shoebox_axial_mode_pressure() {
    let width = 1.0;
    let depth = 0.8;
    let height = 0.7;
    let source = Point3D::new(0.16, 0.31, 0.29);
    let listeners = vec![
        Point3D::new(0.10, 0.31, 0.29),
        Point3D::new(0.25, 0.31, 0.29),
        Point3D::new(0.75, 0.31, 0.29),
        Point3D::new(0.90, 0.31, 0.29),
    ];
    let mut sim = RoomSimulation::new(
        RoomGeometry::Rectangular(RectangularRoom::new(width, depth, height)),
        vec![Source::omnidirectional(source, 1.0)],
        listeners,
    );
    let axial_frequency =
        rectangular_mode_frequency(1, 0, 0, width, depth, height, sim.speed_of_sound);
    // Stay just off the pole so this validates the modal pressure field rather
    // than the linear solver's treatment of an exactly singular rigid cavity.
    sim.frequencies = vec![axial_frequency + 1.0];
    let output = run_fem_with_mesh(
        &sim,
        &FemMeshConfig {
            fine_radius: 0.35,
            modal_damping_ratio: DEFAULT_MODAL_DAMPING_RATIO,
            ..FemMeshConfig::default()
        },
    )
    .expect("rigid shoebox modal pressure solve should converge");

    let numerical: Vec<Complex64> = output.pressures[0]
        .iter()
        .map(|listener| listener[0])
        .collect();
    let analytical: Vec<f64> = [0.10, 0.25, 0.75, 0.90]
        .into_iter()
        .map(|x| (std::f64::consts::PI * x / width).cos())
        .collect();
    // Fit the arbitrary complex source normalization, then compare the
    // spatial pressure shape against the closed-form Neumann (1,0,0) mode.
    let denominator = analytical.iter().map(|value| value * value).sum::<f64>();
    let scale = analytical
        .iter()
        .zip(&numerical)
        .map(|(&shape, &pressure)| pressure * shape)
        .sum::<Complex64>()
        / denominator;
    let error = analytical
        .iter()
        .zip(&numerical)
        .map(|(&shape, &pressure)| (pressure - scale * shape).norm_sqr())
        .sum::<f64>()
        .sqrt();
    let reference = numerical
        .iter()
        .map(|pressure| pressure.norm_sqr())
        .sum::<f64>()
        .sqrt();
    let relative_error = error / reference.max(f64::MIN_POSITIVE);
    assert!(
        relative_error < 0.25,
        "full fem_runner pressure field missed the closed-form axial mode: relative L2 error={relative_error:.3}"
    );
    assert!(
        (numerical[0] / numerical[3]).re < 0.0,
        "opposite sides of the (1,0,0) mode must have opposite pressure phase"
    );
}
#[test]
fn test_wall_absorption_reduces_first_axial_modal_peak() {
    let width = 0.343;
    let depth = 0.29;
    let height = 0.25;
    let mut rigid = RoomSimulation::new(
        RoomGeometry::Rectangular(RectangularRoom::new(width, depth, height)),
        vec![Source::omnidirectional(Point3D::new(0.07, 0.11, 0.09), 1.0)],
        vec![Point3D::new(0.27, 0.19, 0.16)],
    );
    let expected_first_axial =
        rectangular_mode_frequency(1, 0, 0, width, depth, height, rigid.speed_of_sound);
    rigid.frequencies = vec![
        expected_first_axial - 28.0,
        expected_first_axial - 14.0,
        expected_first_axial,
        expected_first_axial + 14.0,
        expected_first_axial + 28.0,
    ];
    let absorption = SurfaceConfig::Absorption { coefficient: 0.30 };
    let mut absorbed = rigid.clone();
    absorbed.boundaries = BoundaryConfig {
        floor: absorption.clone(),
        ceiling: absorption.clone(),
        walls: absorption,
        front_wall: None,
        back_wall: None,
        left_wall: None,
        right_wall: None,
    };
    let mesh_config = FemMeshConfig {
        fine_radius: 0.18,
        modal_damping_ratio: 0.003,
        ..FemMeshConfig::default()
    };
    let rigid_output =
        run_fem_with_mesh(&rigid, &mesh_config).expect("rigid modal sweep should converge");
    let absorbed_output =
        run_fem_with_mesh(&absorbed, &mesh_config).expect("absorbed modal sweep should converge");
    let rigid_magnitudes: Vec<f64> = rigid_output.pressures[0][0]
        .iter()
        .map(|p| p.norm())
        .collect();
    let absorbed_magnitudes: Vec<f64> = absorbed_output.pressures[0][0]
        .iter()
        .map(|p| p.norm())
        .collect();
    let rigid_peak = rigid_magnitudes.iter().copied().fold(0.0, f64::max);
    let absorbed_peak = absorbed_magnitudes.iter().copied().fold(0.0, f64::max);
    assert!(
        absorbed_peak < rigid_peak * 0.75,
        "absorptive walls should reduce the first axial modal peak: rigid={rigid_peak:.3e}, absorbed={absorbed_peak:.3e}"
    );
}
