#[test]
fn test_iso_9613_air_absorption_matches_published_values() {
    let alpha_to_db_per_100m =
        |np_per_m: f64| -> f64 { np_per_m * (20.0 / std::f64::consts::LN_10) * 100.0 };
    let a_1k = alpha_to_db_per_100m(iso_9613_air_absorption_np_per_m(1_000.0));
    assert!(
        (0.2..1.5).contains(&a_1k),
        "1 kHz absorption {a_1k:.3} dB/100 m outside expected band"
    );
    let a_4k = alpha_to_db_per_100m(iso_9613_air_absorption_np_per_m(4_000.0));
    assert!(
        (2.0..8.0).contains(&a_4k),
        "4 kHz absorption {a_4k:.3} dB/100 m outside expected band"
    );
    let a_100 = alpha_to_db_per_100m(iso_9613_air_absorption_np_per_m(100.0));
    assert!(
        a_100 < 0.05,
        "100 Hz absorption should be vanishingly small, got {a_100:.4} dB/100 m"
    );
}
#[test]
fn test_complex_wavenumber_uses_configured_modal_damping_floor() {
    let k = 10.0;
    let frequency = 100.0;
    let default_damped = complex_wavenumber(k, frequency, DEFAULT_MODAL_DAMPING_RATIO);
    assert_eq!(default_damped.re, k);
    assert!((default_damped.im - 0.005).abs() < 1.0e-12);
    assert!(
        DEFAULT_MODAL_DAMPING_RATIO < 0.001,
        "default volume damping must remain a numerical floor, not a room-loss model"
    );
    let custom_damped = complex_wavenumber(k, frequency, 0.02);
    assert!((custom_damped.im - 0.2).abs() < 1.0e-12);
    let atmospheric_only = complex_wavenumber(k, frequency, 0.0);
    assert!(atmospheric_only.im < default_damped.im);
    assert!(atmospheric_only.im >= 0.0);
}
#[test]
fn test_passive_volume_and_wall_losses_have_same_operator_sign() {
    let k = 10.0;
    let k_complex = complex_wavenumber(k, 100.0, 0.01);
    let volume_imaginary_coefficient = -(k_complex * k_complex).im;
    let wall_imaginary_coefficient = ResolvedBoundary::Admittance(Complex64::new(0.2, 0.0))
        .admittance_term(k, 100.0)
        .unwrap()
        .im;
    assert!(volume_imaginary_coefficient < 0.0);
    assert!(
        wall_imaginary_coefficient < 0.0,
        "passive wall loss must reinforce volume loss under exp(-iωt)"
    );
}

