#[test]
fn checked_tbem_admittance_rejects_invalid_materials_and_frequencies() {
    let room = RectangularRoom::new(1.0, 1.0, 1.0);
    let mesh = room.generate_mesh(1);
    let mut sim = RoomSimulation::new(RoomGeometry::Rectangular(room), Vec::new(), Vec::new());
    assert!(try_tbem_element_admittance(&sim, &mesh, 0.0).is_err());
    assert!(try_tbem_element_admittance(&sim, &mesh, f64::NAN).is_err());
    assert!(try_tbem_element_admittance(&sim, &mesh, 125.0).is_ok());
    sim.boundaries.floor = SurfaceConfig::Impedance {
        real: f64::NAN,
        imag: 0.0,
    };
    assert!(try_tbem_element_admittance(&sim, &mesh, 125.0).is_err());
}
#[test]
fn test_combined_passive_losses_strengthen_dissipative_quadratic_form() {
    let k = 10.0;
    let k_complex = complex_wavenumber(k, 100.0, 0.01);
    let volume_mass_quadratic_form = 2.5;
    let boundary_mass_quadratic_form = 0.75;
    let wall = ResolvedBoundary::Admittance(Complex64::new(0.2, 0.0))
        .admittance_term(k, 100.0)
        .unwrap();
    let volume_only = -(k_complex * k_complex) * volume_mass_quadratic_form;
    let combined = volume_only + wall * boundary_mass_quadratic_form;
    assert!(volume_only.im < 0.0);
    assert!(
        combined.im < volume_only.im,
        "adding a passive wall must make Im(xᴴAx) more dissipative: volume={volume_only}, combined={combined}"
    );
}
