#[test]
fn test_absorption_backfit_is_monotonic_at_reference_frequency() {
    let medium = AmbientMedium::new(AIR_DENSITY, 343.0);
    let targets = [0.10, 0.20, 0.30];
    let mut realized = Vec::new();
    for target in targets {
        let resolved = resolve_surface(
            &SurfaceConfig::Absorption {
                coefficient: target,
            },
            medium,
        )
        .unwrap();
        let ResolvedBoundary::PorousLayer { layer, medium } = resolved else {
            panic!("absorption coefficient {target} should resolve to a porous layer");
        };
        realized.push(
            layer
                .try_absorption_coefficient(ABSORPTION_REFERENCE_FREQ, medium)
                .unwrap(),
        );
    }
    for pair in realized.windows(2) {
        assert!(
            pair[1] > pair[0],
            "higher requested absorption should produce higher realized absorption: {realized:?}"
        );
    }
    for (target, actual) in targets.into_iter().zip(realized) {
        assert!(
            (target - actual).abs() < 0.01,
            "backfit should match alpha={target:.2} at {ABSORPTION_REFERENCE_FREQ:.0} Hz, got {actual:.3}"
        );
    }
}
