fn cuda_fem_f32_smoke_matches_cpu_tiny_room() {
    if sonium_compute::CudaBackend::new(0).is_err() {
        eprintln!("no CUDA device — skipping");
        return;
    }
    let room = RectangularRoom::new(0.9, 0.8, 0.7);
    let source = Source::omnidirectional(Point3D::new(0.22, 0.31, 0.28), 1.0);
    let lp = Point3D::new(0.68, 0.53, 0.42);
    let sim = RoomSimulation::with_frequencies(
        RoomGeometry::Rectangular(room),
        vec![source],
        vec![lp],
        80.0,
        80.0,
        1,
    );
    let cfg = FemMeshConfig {
        fine_radius: 0.2,
        modal_damping_ratio: 0.02,
        ..FemMeshConfig::default()
    };
    let cpu = run_fem_with_mesh(&sim, &cfg).expect("tiny CPU FEM solve should converge");
    let (cuda, diagnostics) =
        run_fem_gpu_report(&sim, &cfg, GpuPrecision::F32Pure, GpuPrecond::Amg, 0)
            .expect("tiny CUDA FEM solve should run");
    diagnostics
        .require_converged()
        .expect("tiny CUDA FEM solve should converge");
    let cpu_p = cpu.pressures[0][0][0];
    let cuda_p = cuda.pressures[0][0][0];
    assert!(cuda_p.re.is_finite() && cuda_p.im.is_finite());
    assert!(cuda_p.norm() > 0.0, "CUDA pressure should be non-zero");
    let rel = (cpu_p - cuda_p).norm() / cpu_p.norm().max(1.0e-12);
    assert!(
        rel < 0.25,
        "CUDA pressure drifted too far from CPU: cpu={cpu_p:?}, cuda={cuda_p:?}, rel={rel:.3e}"
    );
}

