#[test]
fn test_all_preconditioner_kinds_apply() {
    let matrix = CsrMatrix::from_raw_parts(
        4,
        4,
        vec![0, 2, 5, 8, 10],
        vec![0, 1, 0, 1, 2, 1, 2, 3, 2, 3],
        vec![
            Complex64::new(4.0, 0.1),
            Complex64::new(-1.0, 0.0),
            Complex64::new(-1.0, 0.0),
            Complex64::new(4.0, 0.1),
            Complex64::new(-1.0, 0.0),
            Complex64::new(-1.0, 0.0),
            Complex64::new(4.0, 0.1),
            Complex64::new(-1.0, 0.0),
            Complex64::new(-1.0, 0.0),
            Complex64::new(4.0, 0.1),
        ],
    );
    let rhs = vec![Complex64::new(1.0, 0.0); 4];
    let ilut_config = IlutConfig::default();
    for kind in [
        FemPreconditionerKind::Ilut,
        FemPreconditionerKind::BlockJacobi,
        FemPreconditionerKind::AdditiveSchwarz,
        FemPreconditionerKind::Oras,
        FemPreconditionerKind::Habc,
        FemPreconditionerKind::SweepingSchwarz,
        FemPreconditionerKind::IluColoring,
        FemPreconditionerKind::IluFixedPoint,
        FemPreconditionerKind::Amg,
    ] {
        let preconditioner = build_preconditioner(&matrix, kind, &ilut_config, 2.0, None);
        let y = preconditioner.apply(&rhs);
        assert_eq!(y.len(), rhs.len(), "{kind}");
        assert!(
            y.iter().all(|v| v.re.is_finite() && v.im.is_finite()),
            "{kind}"
        );
    }
}
