#[test]
fn test_recycled_gmres_path_solves_and_populates_subspace() {
    let matrix = CsrMatrix::from_raw_parts(
        4,
        4,
        vec![0, 2, 5, 8, 10],
        vec![0, 1, 0, 1, 2, 1, 2, 3, 2, 3],
        vec![
            Complex64::new(4.0, 0.1),
            Complex64::new(-1.0, 0.0),
            Complex64::new(-1.0, 0.0),
            Complex64::new(4.0, 0.1),
            Complex64::new(-1.0, 0.0),
            Complex64::new(-1.0, 0.0),
            Complex64::new(4.0, 0.1),
            Complex64::new(-1.0, 0.0),
            Complex64::new(-1.0, 0.0),
            Complex64::new(4.0, 0.1),
        ],
    );
    let rhs = vec![Complex64::new(1.0, 0.0); 4];
    let preconditioner = build_preconditioner(
        &matrix,
        FemPreconditionerKind::Ilut,
        &IlutConfig::default(),
        1.0,
        None,
    );
    let config = GmresConfig {
        max_iterations: 20,
        restart: 4,
        tolerance: 1e-10,
        convergence_check_interval: 1,
        min_restart: None,
        max_restart: None,
        ..Default::default()
    };
    let mut subspace = FemRecycleSubspace(GcroDrSubspace::new(2));
    let solution = solve_frequency_system(
        &matrix,
        &preconditioner,
        &rhs,
        None,
        Some(&mut subspace),
        &config,
    );
    assert!(solution.converged);
    assert!(subspace.0.is_populated());
    let ax = matrix.matvec(&solution.x);
    let error: f64 = ax
        .iter()
        .zip(rhs.iter())
        .map(|(a, b)| (*a - *b).norm_sqr())
        .sum::<f64>()
        .sqrt();
    assert!(error < 1e-8, "recycled solve error too large: {error}");
}
#[test]
fn test_symmetric_vs_full_solve() {
    let sim = symmetric_stereo_sim();
    let cfg = FemMeshConfig {
        preconditioner: FemPreconditionerKind::Ilut,
        recycle_subspace_size: 0,
        ..FemMeshConfig::default()
    };
    let full = run_fem_full(&sim, &cfg).expect("full solve failed");
    let sym =
        run_fem_symmetric(&sim, &detect_symmetry(&sim), &cfg).expect("symmetric solve failed");
    assert_eq!(full.pressures.len(), sym.pressures.len());
    for src in 0..full.pressures.len() {
        for lp in 0..full.pressures[src].len() {
            for f in 0..full.pressures[src][lp].len() {
                let pf = full.pressures[src][lp][f];
                let ps = sym.pressures[src][lp][f];
                let diff = (pf - ps).norm();
                let scale = pf.norm().max(1e-15);
                assert!(
                    diff < 3.0e-2 || diff / scale < 0.30,
                    "src={src} lp={lp} f={f}: full={pf:.6} sym={ps:.6} abs_err={diff:.4e} rel_err={:.4}",
                    diff / scale,
                );
            }
        }
    }
}

/// Compare full-domain and symmetric-path pressures at every source/LP/frequency.
fn assert_full_vs_sym_pressures(full: &SimulationOutput, sym: &SimulationOutput, rel_tol: f64) {
    assert_eq!(full.pressures.len(), sym.pressures.len());
    for src in 0..full.pressures.len() {
        for lp in 0..full.pressures[src].len() {
            for f in 0..full.pressures[src][lp].len() {
                let pf = full.pressures[src][lp][f];
                let ps = sym.pressures[src][lp][f];
                let diff = (pf - ps).norm();
                let scale = pf.norm().max(1e-15);
                assert!(
                    diff < 3.0e-2 || diff / scale < rel_tol,
                    "src={src} lp={lp} f={f}: full={pf:.6} sym={ps:.6} abs_err={diff:.4e} rel_err={:.4}",
                    diff / scale,
                );
            }
        }
    }
}

/// Directional stereo pair: cardioid sources at x=0.8 / x=2.2 (mirror about
/// x=1.5) pointing AWAY from the symmetry plane (−x and +x). The cardioid
/// pattern is frequency-independent, so the directivity is fully active even
/// on the cheap low-frequency sweep. The mirrored-side source is listed
/// FIRST: that makes it the dedup primary, which is exactly the case where
/// the symmetric path must mirror its orientation into the reduced domain.
///
/// Two test-design constraints, both from the structured 6-tet mesher:
///  - The sweep tops out at 200 Hz so the full (3.0 m) and half (1.5 m)
///    domains round to the SAME element spacing (0.25 m); then the reduced
///    mesh coincides exactly with the full mesh's left half and the two paths
///    agree to solver tolerance there. (At e.g. 150 Hz the spacings round to
///    1/3 m vs 0.3 m and the comparison degrades to discretisation noise.)
///  - All LPs sit inside the reduced domain (x ≤ 1.5). Points in the mirrored
///    half are evaluated on the full mesh's right half, whose alternating tet
///    split is NOT mirror-symmetric — the full path disagrees with its own
///    mirror image there, which would swamp the comparison.
fn symmetric_cardioid_sim() -> RoomSimulation {
    let room = RectangularRoom::new(3.0, 3.0, 2.4);
    let mk = |x, orientation: Point3D, name: &str| Source {
        position: Point3D::new(x, 0.3, 1.1),
        orientation,
        directivity: Directivity::Grid(DirectivityGrid::cardioid()),
        amplitude: 1.0,
        crossover: CrossoverFilter::FullRange,
        name: name.to_string(),
    };
    let right = mk(2.2, Point3D::new(1.0, 0.0, 0.0), "right");
    let left = mk(0.8, Point3D::new(-1.0, 0.0, 0.0), "left");
    // LP0 sits inside the left source's lobe (and near the right one's null),
    // LP1 is on-axis in front of the left lobe, LP2 is a generic off-axis
    // position on the symmetry plane.
    let lps = vec![
        Point3D::new(0.5, 0.8, 1.1),
        Point3D::new(0.3, 0.3, 1.1),
        Point3D::new(1.5, 2.0, 1.1),
    ];
    RoomSimulation::with_frequencies(
        RoomGeometry::Rectangular(room),
        vec![right, left],
        lps,
        50.0,
        200.0,
        5,
    )
}

#[test]
fn test_symmetric_vs_full_solve_directional_cardioid() {
    let sim = symmetric_cardioid_sim();
    let sym_cfg = detect_symmetry(&sim);
    assert!(
        sym_cfg.has_x(),
        "cardioid stereo pair should keep X symmetry"
    );
    let cfg = FemMeshConfig {
        preconditioner: FemPreconditionerKind::Ilut,
        recycle_subspace_size: 0,
        ..FemMeshConfig::default()
    };
    let full = run_fem_full(&sim, &cfg).expect("full solve failed");
    let sym = run_fem_symmetric(&sim, &sym_cfg, &cfg).expect("symmetric solve failed");
    // An unmirrored orientation swaps each lobe for its mirror image (O(1)
    // relative error at these LPs before the fix); with the aligned meshes
    // above the paths agree to solver tolerance, so 0.10 is a tight bound.
    assert_full_vs_sym_pressures(&full, &sym, 0.10);
}

/// Left/right-asymmetric pattern: lobe toward local +X, so the grid is NOT
/// invariant under the mirror flip phi -> 180° - phi. A mirror pair of these
/// maps to two DIFFERENT reduced-domain patterns, so the symmetric path must
/// not share one solve between them.
fn asymmetric_lr_grid() -> DirectivityGrid {
    let horizontal_angles: Vec<f64> = (0..36).map(|i| i as f64 * 10.0).collect();
    let vertical_angles: Vec<f64> = (0..19).map(|i| i as f64 * 10.0).collect();
    let mut magnitude = HostMatrix::<f64>::zeros(vertical_angles.len(), horizontal_angles.len());
    for (v_idx, &v_angle) in vertical_angles.iter().enumerate() {
        for (h_idx, &h_angle) in horizontal_angles.iter().enumerate() {
            let theta = v_angle.to_radians();
            let phi = h_angle.to_radians();
            // Lobe toward local +X (phi = 0): breaks the phi -> 180° - phi
            // mirror symmetry of the built-in cardioid.
            magnitude[[v_idx, h_idx]] = 0.5 * (1.0 + theta.sin() * phi.cos());
        }
    }
    DirectivityGrid::try_new(horizontal_angles, vertical_angles, magnitude)
        .expect("test grid is valid")
}

#[test]
fn test_symmetric_vs_full_solve_directional_asymmetric_grid() {
    let room = RectangularRoom::new(3.0, 3.0, 2.4);
    let mk = |x, orientation: Point3D, name: &str| Source {
        position: Point3D::new(x, 0.3, 1.1),
        orientation,
        directivity: Directivity::Grid(asymmetric_lr_grid()),
        amplitude: 1.0,
        crossover: CrossoverFilter::FullRange,
        name: name.to_string(),
    };
    let left = mk(0.8, Point3D::new(-1.0, 0.0, 0.0), "left");
    let right = mk(2.2, Point3D::new(1.0, 0.0, 0.0), "right");
    let lps = vec![
        Point3D::new(0.5, 0.8, 1.1),
        Point3D::new(0.3, 0.3, 1.1),
        Point3D::new(1.5, 2.0, 1.1),
    ];
    let sim = RoomSimulation::with_frequencies(
        RoomGeometry::Rectangular(room),
        vec![left, right],
        lps,
        50.0,
        200.0,
        5,
    );
    let sym_cfg = detect_symmetry(&sim);
    assert!(sym_cfg.has_x(), "mirror pair should keep X symmetry");
    let cfg = FemMeshConfig {
        preconditioner: FemPreconditionerKind::Ilut,
        recycle_subspace_size: 0,
        ..FemMeshConfig::default()
    };
    let full = run_fem_full(&sim, &cfg).expect("full solve failed");
    let sym = run_fem_symmetric(&sim, &sym_cfg, &cfg).expect("symmetric solve failed");
    // Same mesh-alignment reasoning as the cardioid test; before the fix the
    // position-only dedup merged this pair into one unmirrored-orientation
    // solve (O(1) relative error at these LPs).
    assert_full_vs_sym_pressures(&full, &sym, 0.10);
}

// ---------------------------------------------------------------------------
// Block multi-source solve (block_source_solve) tests
// ---------------------------------------------------------------------------

/// Asymmetric multi-source fixture: sources are deliberately NOT mirror
/// pairs so `detect_symmetry` stays empty and `run_fem_with_mesh` takes the
/// full-domain path where the block source solve lives.
#[cfg(test)]
fn multi_source_sim(n_sources: usize, frequencies: Vec<f64>) -> RoomSimulation {
    let positions = [
        Point3D::new(0.18, 0.31, 0.29),
        Point3D::new(0.65, 0.42, 0.35),
        Point3D::new(0.40, 0.60, 0.20),
        Point3D::new(0.80, 0.15, 0.50),
    ];
    let sources: Vec<Source> = positions[..n_sources]
        .iter()
        .map(|&p| Source::omnidirectional(p, 1.0))
        .collect();
    let mut sim = RoomSimulation::new(
        RoomGeometry::Rectangular(RectangularRoom::new(1.0, 0.8, 0.7)),
        sources,
        vec![
            Point3D::new(0.83, 0.57, 0.41),
            Point3D::new(0.25, 0.45, 0.55),
        ],
    );
    sim.frequencies = frequencies;
    let sym = detect_symmetry(&sim);
    assert!(
        sym.planes.is_empty(),
        "fixture must stay asymmetric, got {sym:?}"
    );
    sim
}

#[test]
fn test_block_source_solve_matches_per_source_path() {
    let sim = multi_source_sim(3, vec![320.0, 455.0, 590.0, 725.0]);
    let base = FemMeshConfig {
        preconditioner: FemPreconditionerKind::Ilut,
        recycle_subspace_size: 0,
        modal_damping_ratio: 0.003,
        ..FemMeshConfig::default()
    };
    let serial = run_fem_full(&sim, &base).expect("per-source solve should converge");
    let block = run_fem_full(
        &sim,
        &FemMeshConfig {
            block_source_solve: true,
            ..base
        },
    )
    .expect("block solve should converge");

    assert_eq!(serial.pressures.len(), block.pressures.len());
    for (src, (serial_src, block_src)) in serial
        .pressures
        .iter()
        .zip(block.pressures.iter())
        .enumerate()
    {
        for (lp, (serial_lp, block_lp)) in serial_src.iter().zip(block_src.iter()).enumerate() {
            for (f, (&ps, &pb)) in serial_lp.iter().zip(block_lp.iter()).enumerate() {
                // Both paths solve to the same 1e-6 true-residual tolerance;
                // near modal peaks the pressure field amplifies residual
                // differences, so compare against a tolerance-scaled bound.
                let scale = ps.norm().max(pb.norm()).max(1e-9);
                assert!(
                    (ps - pb).norm() <= 1e-2 * scale,
                    "src {src} lp {lp} freq {f}: block {pb:e} vs per-source {ps:e}"
                );
            }
        }
    }
}

#[test]
fn test_block_source_solve_flexible_preconditioner_path() {
    // AMG is the flexible-outer preconditioner: the block path must dispatch
    // to block FGMRES and still converge.
    let sim = multi_source_sim(2, vec![400.0, 620.0]);
    let cfg = FemMeshConfig {
        preconditioner: FemPreconditionerKind::Amg,
        recycle_subspace_size: 0,
        block_source_solve: true,
        modal_damping_ratio: 0.003,
        ..FemMeshConfig::default()
    };
    let output = run_fem_full(&sim, &cfg).expect("block FGMRES path should converge");
    for src in &output.pressures {
        for lp in src {
            for p in lp {
                assert!(p.is_finite(), "block FGMRES pressure must be finite");
            }
        }
    }
}

#[test]
fn test_block_source_solve_falls_back_on_nonconvergence() {
    // gmres_restart = 1 makes the block solve stall far above tolerance, so
    // every source fails the per-RHS true-residual gate; the run must still
    // succeed via the existing per-source retry ladder (strong ILUT +
    // bounded BiCGSTAB), and the pressures must match a normal solve.
    let sim = multi_source_sim(2, vec![455.0]);
    let reference = run_fem_full(
        &sim,
        &FemMeshConfig {
            preconditioner: FemPreconditionerKind::Ilut,
            recycle_subspace_size: 0,
            modal_damping_ratio: 0.003,
            ..FemMeshConfig::default()
        },
    )
    .expect("reference solve should converge");

    let forced = run_fem_full(
        &sim,
        &FemMeshConfig {
            preconditioner: FemPreconditionerKind::Ilut,
            recycle_subspace_size: 0,
            block_source_solve: true,
            gmres_restart: 1,
            modal_damping_ratio: 0.003,
            ..FemMeshConfig::default()
        },
    )
    .expect("fallback ladder should recover from a stalled block solve");

    for (src, (ref_src, forced_src)) in reference
        .pressures
        .iter()
        .zip(forced.pressures.iter())
        .enumerate()
    {
        for (lp, (ref_lp, forced_lp)) in ref_src.iter().zip(forced_src.iter()).enumerate() {
            let (pr, pf) = (ref_lp[0], forced_lp[0]);
            let scale = pr.norm().max(pf.norm()).max(1e-9);
            // The fallback solves through a different preconditioner
            // (strong ILUT with the fallback shift, then bounded BiCGSTAB);
            // both sides meet the 1e-6 true-residual gate but near-modal
            // pressure amplification makes the paths differ by ~1%.
            assert!(
                (pr - pf).norm() <= 5e-2 * scale,
                "src {src} lp {lp}: fallback {pf:e} vs reference {pr:e}"
            );
        }
    }
}

/// Timing fixture for the block-vs-per-source trade-off. Run explicitly:
///
/// ```sh
/// cargo test -p sonium-sim-room --release block_source_timing -- --ignored --nocapture
/// ```
///
/// Reports wall-clock for the block path (which parallelises only inside
/// the operator/preconditioner applies) vs the parallel per-source path at
/// 2 and 4 sources.
#[test]
#[ignore = "timing fixture, run explicitly"]
fn block_source_timing_fixture() {
    let frequencies: Vec<f64> = (0..8).map(|i| 300.0 + i as f64 * 60.0).collect();
    for &n_sources in &[2usize, 4] {
        let sim = multi_source_sim(n_sources, frequencies.clone());
        let base = FemMeshConfig {
            preconditioner: FemPreconditionerKind::Ilut,
            recycle_subspace_size: 0,
            modal_damping_ratio: 0.003,
            ..FemMeshConfig::default()
        };
        let t0 = std::time::Instant::now();
        let serial = run_fem_full(&sim, &base).expect("per-source solve");
        let t_serial = t0.elapsed();
        let t0 = std::time::Instant::now();
        let block = run_fem_full(
            &sim,
            &FemMeshConfig {
                block_source_solve: true,
                ..base
            },
        )
        .expect("block solve");
        let t_block = t0.elapsed();
        // Sanity: both paths agree, so the timing compares real work.
        let ps = serial.pressures[0][0][0];
        let pb = block.pressures[0][0][0];
        assert!((ps - pb).norm() <= 1e-2 * ps.norm().max(1e-9));
        eprintln!(
            "sources={n_sources}: per-source={:?} block={:?} speedup={:.2}x",
            t_serial,
            t_block,
            t_serial.as_secs_f64() / t_block.as_secs_f64()
        );
    }
}

#[test]
fn configured_wavelength_resolution_controls_exported_mesh() {
    let simulation = sonium_xem::RoomSimulation::new(
        sonium_xem::RoomGeometry::Rectangular(sonium_xem::RectangularRoom::new(1.0, 1.0, 1.0)),
        Vec::new(),
        Vec::new(),
    );
    let mut simulation = simulation;
    simulation.frequencies = vec![343.0];
    let coarse =
        super::build::build_full_domain_room_mesh(&simulation, &FemMeshConfig::default()).unwrap();
    let config = FemMeshConfig {
        elements_per_wavelength: 12.0,
        ..FemMeshConfig::default()
    };
    let fine = super::build::build_full_domain_room_mesh(&simulation, &config).unwrap();
    assert!(fine.num_nodes() > coarse.num_nodes());
    assert!(fine.num_elements() > coarse.num_elements());
    for value in [0.0, 1.0, f64::NAN, f64::INFINITY] {
        let config = FemMeshConfig {
            elements_per_wavelength: value,
            ..FemMeshConfig::default()
        };
        assert!(super::build::build_full_domain_room_mesh(&simulation, &config).is_err());
    }
}
